@Tags(['golden'])
library;

import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:zaghlol/features/zakah/presentation/zakah_screen.dart';

import '../../support/golden_matrix.dart';
import 'zakah_ui_test.dart' as base;

// Goldens are generated by CI (`--update-goldens`); PNGs are not committed.
void main() {
  for (final v in [...goldenVariants, ...goldenVariantsScaled]) {
    testWidgets('zakah golden ${v.name}', (tester) async {
      final env = await base.zEnv(tester);
      await base.seedAssets(env, tester);
      await base.pumpZakah(
        tester,
        env,
        const ZakahScreen(),
        locale: v.locale,
        dark: v.dark,
        scale: v.textScale,
      );
      await expectLater(
        find.byType(MaterialApp),
        matchesGoldenFile('../../goldens/zakah_${v.name}.png'),
      );
    });
  }
}
